-- FitTrack Phase 6: metadata for the initial library of original 3D exercise demos.
--
-- The GLB files are static assets (public/models/exercises, generated by
-- scripts/generate-exercise-models.mjs); these rows link them to the shared
-- catalog exercises by name. Idempotent: re-running inserts nothing new.

insert into public.exercise_animations (exercise_id, asset_path, metadata)
select e.id, v.asset_path, v.metadata
from (
  values
  ('Back Squat', '/models/exercises/back-squat.glb', '{"primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings","core"],"durationSeconds":3.4,"clip":"demo"}'::jsonb),
  ('Goblet Squat', '/models/exercises/goblet-squat.glb', '{"primaryMuscles":["quads","glutes"],"secondaryMuscles":["core"],"durationSeconds":3.2,"clip":"demo"}'::jsonb),
  ('Barbell Bench Press', '/models/exercises/barbell-bench-press.glb', '{"primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders"],"durationSeconds":3,"clip":"demo"}'::jsonb),
  ('Push-Up', '/models/exercises/push-up.glb', '{"primaryMuscles":["chest"],"secondaryMuscles":["triceps","shoulders","core"],"durationSeconds":2.6,"clip":"demo"}'::jsonb),
  ('Deadlift', '/models/exercises/deadlift.glb', '{"primaryMuscles":["back","hamstrings","glutes"],"secondaryMuscles":["forearms","core"],"durationSeconds":3.6,"clip":"demo"}'::jsonb),
  ('Romanian Deadlift', '/models/exercises/romanian-deadlift.glb', '{"primaryMuscles":["hamstrings","glutes"],"secondaryMuscles":["back"],"durationSeconds":3.6,"clip":"demo"}'::jsonb),
  ('Overhead Press', '/models/exercises/overhead-press.glb', '{"primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","core"],"durationSeconds":3,"clip":"demo"}'::jsonb),
  ('Barbell Row', '/models/exercises/barbell-row.glb', '{"primaryMuscles":["back"],"secondaryMuscles":["biceps","rear delts"],"durationSeconds":2.6,"clip":"demo"}'::jsonb),
  ('Pull-Up', '/models/exercises/pull-up.glb', '{"primaryMuscles":["back"],"secondaryMuscles":["biceps"],"durationSeconds":3.2,"clip":"demo"}'::jsonb),
  ('Walking Lunge', '/models/exercises/walking-lunge.glb', '{"primaryMuscles":["quads","glutes"],"secondaryMuscles":["hamstrings"],"durationSeconds":4.4,"clip":"demo"}'::jsonb),
  ('Lateral Raise', '/models/exercises/lateral-raise.glb', '{"primaryMuscles":["shoulders"],"secondaryMuscles":[],"durationSeconds":2.8,"clip":"demo"}'::jsonb),
  ('Dumbbell Curl', '/models/exercises/dumbbell-curl.glb', '{"primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"durationSeconds":2.6,"clip":"demo"}'::jsonb)
) as v (exercise_name, asset_path, metadata)
join public.exercises e on e.owner_user_id is null and lower(e.name) = lower(v.exercise_name)
on conflict (exercise_id, asset_path) do nothing;
